// Shared HTML for every email GhostSwap sends: the draw notice (lib/email.ts) and the
// Supabase auth emails (supabase/templates, generated by scripts/build-auth-emails.ts).
// Email clients ignore web fonts and most CSS, so this sticks to tables and inline styles.

const APP_URL = 'https://ghostswap.nvrkth.com'
const INK = '#1b1b1a'
const GRAPHITE = '#4f4f49'
const FAINT = '#7d7d76'
const RULE = '#e7e7e3'
const SANS = "-apple-system, BlinkMacSystemFont, 'Segoe UI', Helvetica, Arial, sans-serif"

export function escapeHtml(text: string) {
  return text
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;')
}

interface LayoutParams {
  title: string
  label: string
  paragraphs: string[]
  cta: { text: string; href: string }
  note: string
}

// Values passed in must already be safe HTML: escape user input before calling.
export function emailLayout({ title, label, paragraphs, cta, note }: LayoutParams) {
  const body = paragraphs
    .map(
      (p) =>
        `<p style="margin: 0 0 14px; font-size: 17px; line-height: 26px; color: ${GRAPHITE};">${p}</p>`
    )
    .join('\n                ')

  return `<!DOCTYPE html>
<html lang="es">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <meta name="color-scheme" content="light">
  <meta name="supported-color-schemes" content="light">
  <title>${title}</title>
</head>
<body style="margin: 0; padding: 0; background-color: #ffffff; font-family: ${SANS}; color: ${INK};">
  <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse: collapse; background-color: #ffffff;">
    <tr>
      <td align="center" style="padding: 40px 20px;">
        <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width: 480px; border-collapse: collapse;">
          <tr>
            <td style="padding-bottom: 36px;">
              <a href="${APP_URL}" style="text-decoration: none;">
                <img src="${APP_URL}/email-logo.png" width="175" height="30" alt="ghostswap" style="display: block; border: 0;">
              </a>
            </td>
          </tr>
          <tr>
            <td style="border: 1px solid ${RULE}; border-radius: 4px; padding: 32px 28px;">
              <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse: collapse;">
                <tr>
                  <td valign="top">
                    <p style="margin: 0 0 10px; font-size: 15px; font-weight: 600; color: ${GRAPHITE};">${label}</p>
                    <h1 style="margin: 0 0 20px; font-size: 26px; line-height: 32px; font-weight: 400; color: ${INK};">${title}</h1>
                  </td>
                </tr>
              </table>
              ${body}
              <table role="presentation" cellpadding="0" cellspacing="0" style="border-collapse: collapse; margin: 12px 0 4px;">
                <tr>
                  <td style="background-color: ${INK}; border-radius: 2px;">
                    <a href="${cta.href}" style="display: inline-block; padding: 15px 28px; font-family: ${SANS}; font-size: 17px; font-weight: 600; color: #ffffff; text-decoration: none;">${cta.text}</a>
                  </td>
                </tr>
              </table>
            </td>
          </tr>
          <tr>
            <td style="padding: 20px 4px 0;">
              <p style="margin: 0 0 24px; font-size: 14px; line-height: 21px; color: ${FAINT};">${note}</p>
              <p style="margin: 0; font-size: 14px; color: ${FAINT};">
                GhostSwap &middot; <a href="${APP_URL}" style="color: ${FAINT};">ghostswap.nvrkth.com</a>
              </p>
            </td>
          </tr>
        </table>
      </td>
    </tr>
  </table>
</body>
</html>`
}

// Supabase fills {{ .ConfirmationURL }} itself; these are pasted into its auth settings.
export const AUTH_EMAILS = {
  confirmation: {
    subject: 'Confirma tu cuenta de GhostSwap',
    html: emailLayout({
      label: 'Tu cuenta',
      title: 'Confirma tu correo',
      paragraphs: [
        'Para terminar de crear tu cuenta en GhostSwap, confirma que este correo es tuyo.',
      ],
      cta: { text: 'Confirmar mi correo', href: '{{ .ConfirmationURL }}' },
      note: 'Si no creaste una cuenta, ignora este correo. Nadie podrá usarla sin confirmar.',
    }),
  },
  recovery: {
    subject: 'Cambia tu contraseña de GhostSwap',
    html: emailLayout({
      label: 'Tu cuenta',
      title: 'Elige una contraseña nueva',
      paragraphs: [
        'Alguien pidió cambiar la contraseña de esta cuenta. Si fuiste tú, elige una nueva con este botón.',
        'El enlace sirve durante una hora.',
      ],
      cta: { text: 'Elegir contraseña nueva', href: '{{ .ConfirmationURL }}' },
      note: 'Si no lo pediste, ignora este correo. Tu contraseña sigue igual.',
    }),
  },
}
